import functools
@functools.lru_cache(None)
def best(n): return 0 if n == 1 else max(a * (n - a) + best(a) + best(n - a) for a in range(1, n))
@functools.lru_cache(None)
def worst(n): return 0 if n == 1 else min(a * (n - a) + worst(a) + worst(n - a) for a in range(1, n))
assert best(12) == worst(12)
result = best(12)
